Singleton used to define search index field schemas:

```ts
import { defineSearchIndex, search } from "@medusajs/framework/utils"

defineSearchIndex({
  name: "product",
  entity: "product",
  fields: search.define({
    id: search.keyword().filterable(),
    title: search.text().searchable({ weight: 3 }),
  }),
  async *seed() {},
})
```
